package dev.DraGonFiirE.littleperformanceimprovements.client.render;
import java.util.*;import java.util.function.Consumer;import it.unimi.dsi.fastutil.longs.LongArrayList;
/** Integer interval sweep, valid only for an already extracted voxel-union boundary. */
public final class PrimitiveGridOutlineEdges {
 
 private final it.unimi.dsi.fastutil.longs.Long2ObjectOpenHashMap<LongArrayList>[] lines=new it.unimi.dsi.fastutil.longs.Long2ObjectOpenHashMap[]{new it.unimi.dsi.fastutil.longs.Long2ObjectOpenHashMap<>(),new it.unimi.dsi.fastutil.longs.Long2ObjectOpenHashMap<>(),new it.unimi.dsi.fastutil.longs.Long2ObjectOpenHashMap<>()};private double scale;
 public void face(int[] f,double scale){this.scale=scale;add(f[3],f[0]+f[1]*3,f[2],f[4],f[7],f[5],f[6],1);add(f[3],f[0]+f[1]*3,f[2],f[4],f[8],f[5],f[6],-1);add(f[4],f[0]+f[1]*3,f[2],f[3],f[5],f[7],f[8],1);add(f[4],f[0]+f[1]*3,f[2],f[3],f[6],f[7],f[8],-1);}
 private void add(int axis,int normal,int plane,int side,int at,int lo,int hi,int sign){int channel=normal;normal%=3;int u=(axis+1)%3;long key=((long)(u==normal?plane:at)<<32)|((u==normal?at:plane)&0xffffffffL);var events=lines[axis].get(key);if(events==null){events=new LongArrayList(8);lines[axis].put(key,events);}events.add(((long)lo<<4)|(channel<<1)|(sign>0?1:0));events.add(((long)hi<<4)|(channel<<1)|(sign<0?1:0));}
 public void finish(Consumer<SimpleOutlineEdges.Segment> output){int count=0;for(int axis=0;axis<3;axis++){var entries=lines[axis].long2ObjectEntrySet().fastIterator();while(entries.hasNext()){var entry=entries.next();if((count++&255)==0)dev.DraGonFiirE.littleperformanceimprovements.performance.PreviewBuildCancellation.check();var list=entry.getValue();long[] events=list.elements();Arrays.sort(events,0,list.size());int[] balance=new int[6];boolean active=false;int start=0;for(int i=0;i<list.size();){int at=(int)(events[i]>>4);do{long e=events[i++];balance[(int)((e&15)>>1)]+=(e&1)==1?1:-1;}while(i<list.size()&&(int)(events[i]>>4)==at);boolean next=balance[0]!=0||balance[1]!=0||balance[2]!=0||balance[3]!=0||balance[4]!=0||balance[5]!=0;if(!active&&next)start=at;else if(active&&!next&&at>start){long key=entry.getLongKey();double u=(int)(key>>32)*scale,v=(int)key*scale,lo=start*scale,hi=at*scale;output.accept(new SimpleOutlineEdges.Segment(axis==0?new SimpleOutlineEdges.Point(lo,u,v):axis==1?new SimpleOutlineEdges.Point(v,lo,u):new SimpleOutlineEdges.Point(u,v,lo),axis==0?new SimpleOutlineEdges.Point(hi,u,v):axis==1?new SimpleOutlineEdges.Point(v,hi,u):new SimpleOutlineEdges.Point(u,v,hi)));}active=next;}}lines[axis].clear();}}
}
